/** Actual Forge OBJ bake, released batched emitter and authored inventory wrapper; no display required. */
public final class ProgrammerArtworkLegacyChecks {
 private static final Map<String,TextureAtlasSprite> SPRITES=new LinkedHashMap<>();
 private static TextureAtlasSprite sprite(ResourceLocation id){return SPRITES.computeIfAbsent(id.toString(),key->{int index=SPRITES.size();TextureAtlasSprite s=new TextureAtlasSprite(key){};s.setIconWidth(128);s.setIconHeight(128);s.initSprite(1024,1024,index%8*128,index/8*128,false);return s;});}
 private static IModel model(String resource)throws Exception{String[] id=resource.split(":",2);return OBJLoader.INSTANCE.loadModel(new ResourceLocation(id[0],"models/"+id[1])).process(ImmutableMap.of("flip-v","true"));}
 public static void main(String[] args)throws Exception {
  java.lang.reflect.Method initialize=Class.forName("com.vandorlabs.client.PropulsionArtworkLegacyOracle").getDeclaredMethod("initialize");initialize.setAccessible(true);initialize.invoke(null);
  JsonObject manifest;try(java.io.Reader reader=new java.io.InputStreamReader(ProgrammerArtworkLegacyChecks.class.getResourceAsStream("/assets/vandorlabs/data_chip_programmer/data_chip_programmer.json"),java.nio.charset.StandardCharsets.UTF_8)){manifest=new JsonParser().parse(reader).getAsJsonObject();}ProgrammerModelCache cache=ProgrammerModelCache.INSTANCE;varField(cache,"definition",new ProgrammerModelCache.Definition(manifest));cache.format=new net.minecraft.client.renderer.vertex.VertexFormat(DefaultVertexFormats.BLOCK);java.lang.reflect.Field field=ProgrammerModelCache.class.getDeclaredField("meshes");field.setAccessible(true);@SuppressWarnings("unchecked")Map<String,ProgrammerModelCache.Mesh> meshes=(Map<String,ProgrammerModelCache.Mesh>)field.get(cache);meshes.clear();int baked=0;
  for(ProgrammerStatus status:ProgrammerStatus.values())for(Map.Entry<String,JsonElement> entry:manifest.getAsJsonObject("states").getAsJsonObject(status.resourceName).getAsJsonObject("parts").entrySet()){IModel source=model(entry.getValue().getAsJsonObject().get("obj_resource").getAsString());meshes.put(status.resourceName+"/"+entry.getKey(),new ProgrammerModelCache.Mesh(source.bake(source.getDefaultState(),cache.format,ProgrammerArtworkLegacyChecks::sprite),cache.format.getIntegerSize()));baked++;}
  Path output=Paths.get(System.getProperty("vandorlabs.programmerArtworkReference","build/test-artifacts/programmer-artwork-forge.jsonl"));Files.createDirectories(output.toAbsolutePath().getParent());java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");int cases=0,vertices=0;Gson gson=new Gson();try(java.io.Writer writer=Files.newBufferedWriter(output)){
   for(ProgrammerStatus status:ProgrammerStatus.values())for(EnumFacing facing:EnumFacing.HORIZONTALS)for(int mask=0;mask<8;mask++)for(float alpha:new float[]{1F,.35F})for(int light:new int[]{0x00200040,0x00A00070}){BufferBuilder buffer=new BufferBuilder(65536);buffer.begin(7,cache.format);buffer.setTranslation(77,88,99);ProgrammerRenderHelper.append(buffer,cache.definition(),status,facing,mask,3.25,-2.5,17.125,light,alpha);int end=buffer.getVertexCount()*cache.format.getIntegerSize()*4;buffer.pos(0,0,0);for(int axis=0;axis<3;axis++)if(buffer.getByteBuffer().getFloat(end+axis*4)!=0)throw new AssertionError("Released emitter left buffer translation");buffer.finishDrawing();JsonObject row=new JsonObject();row.addProperty("status",status.name());row.addProperty("facing",facing.getIndex());row.addProperty("mask",mask);row.addProperty("alpha",alpha);row.addProperty("light",light);row.addProperty("stride",cache.format.getIntegerSize());row.addProperty("vertices",buffer.getVertexCount());JsonArray data=new JsonArray();ByteBuffer bytes=buffer.getByteBuffer().duplicate().order(ByteOrder.nativeOrder());for(int i=0;i<buffer.getVertexCount()*cache.format.getIntegerSize();i++)data.add(bytes.getInt(i*4));row.add("data",data);write(writer,digest,gson.toJson(row));cases++;vertices+=buffer.getVertexCount();}
   IModel source=model(manifest.getAsJsonObject("states").getAsJsonObject("ready").get("obj_resource").getAsString());IBakedModel item=new ProgrammerItemModel(source.bake(source.getDefaultState(),DefaultVertexFormats.ITEM,ProgrammerArtworkLegacyChecks::sprite));JsonObject row=new JsonObject();row.addProperty("item",true);JsonArray quads=new JsonArray();for(BakedQuad q:item.getQuads(null,null,0)){JsonObject quad=new JsonObject();quad.addProperty("sprite",q.getSprite().getIconName());quad.addProperty("face",q.getFace().getIndex());quad.addProperty("shade",q.shouldApplyDiffuseLighting());JsonArray data=new JsonArray();for(int value:q.getVertexData())data.add(value);quad.add("data",data);quads.add(quad);}row.add("quads",quads);JsonArray transforms=new JsonArray();for(ItemCameraTransforms.TransformType type:ItemCameraTransforms.TransformType.values()){ItemTransformVec3f t=item.getItemCameraTransforms().getTransform(type);JsonArray data=new JsonArray();for(float value:new float[]{t.rotation.x,t.rotation.y,t.rotation.z,t.translation.x,t.translation.y,t.translation.z,t.scale.x,t.scale.y,t.scale.z})data.add(value);transforms.add(data);}row.add("transforms",transforms);write(writer,digest,gson.toJson(row));JsonObject atlas=new JsonObject(),extents=new JsonObject();for(Map.Entry<String,TextureAtlasSprite> entry:SPRITES.entrySet()){TextureAtlasSprite sprite=entry.getValue();JsonArray extent=new JsonArray();extent.add(sprite.getMinU());extent.add(sprite.getMaxU());extent.add(sprite.getMinV());extent.add(sprite.getMaxV());extents.add(entry.getKey(),extent);}atlas.add("sprites",extents);write(writer,digest,gson.toJson(atlas));
  }StringBuilder golden=new StringBuilder();for(byte value:digest.digest())golden.append(String.format(Locale.ROOT,"%02x",value&255));if(baked!=20||cases!=512||vertices!=239616||!golden.toString().equals("9eaca2d0f89efb82c389ad8ceb352e35ca5e7dce39892142346de742d0203621"))throw new AssertionError("Released programmer artwork changed: "+golden);System.out.println("Actual programmer artwork Source PASS models="+baked+" cases="+cases+" vertices="+vertices+" golden="+golden);
 }
 private static void write(java.io.Writer writer,java.security.MessageDigest digest,String text)throws Exception{writer.write(text);writer.write('\n');digest.update((text+"\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 private static void varField(Object target,String name,Object value)throws Exception{java.lang.reflect.Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);field.set(target,value);}
}
